package lexer

import (
	"unicode"

	"github.com/kimjindol2025/freelang-go/pkg/token"
)

// Lexer tokenizes FreeLang source code
type Lexer struct {
	input        string
	position     int  // current position in input (points to current char)
	readPosition int  // current reading position in input (after current char)
	ch           byte // current char under examination
	line         int  // current line number
	column       int  // current column number
	tokens       []token.Token
	indentStack  []int // stack for tracking indentation levels
}

// New creates a new lexer for the given input
func New(input string) *Lexer {
	l := &Lexer{
		input:      input,
		line:       1,
		column:     1,
		tokens:     make([]token.Token, 0),
		indentStack: []int{0}, // start with 0 indentation
	}
	l.readChar()
	return l
}

// readChar reads the next character from the input
func (l *Lexer) readChar() {
	if l.readPosition >= len(l.input) {
		l.ch = 0 // EOF
	} else {
		l.ch = l.input[l.readPosition]
	}
	l.position = l.readPosition
	l.readPosition++

	if l.ch == '\n' {
		l.line++
		l.column = 1
	} else {
		l.column++
	}
}

// peekChar returns the next character without consuming it
func (l *Lexer) peekChar() byte {
	if l.readPosition >= len(l.input) {
		return 0
	}
	return l.input[l.readPosition]
}

// peekCharN returns the nth character ahead
func (l *Lexer) peekCharN(n int) byte {
	pos := l.readPosition + n - 1
	if pos >= len(l.input) {
		return 0
	}
	return l.input[pos]
}

// NextToken returns the next token from the input
func (l *Lexer) NextToken() token.Token {
	var tok token.Token

	l.skipWhitespaceExceptNewline()

	startColumn := l.column
	startLine := l.line

	switch l.ch {
	// Single-character tokens
	case '(':
		tok = l.newToken(token.LPAREN, string(l.ch))
	case ')':
		tok = l.newToken(token.RPAREN, string(l.ch))
	case '{':
		tok = l.newToken(token.LBRACE, string(l.ch))
	case '}':
		tok = l.newToken(token.RBRACE, string(l.ch))
	case '[':
		tok = l.newToken(token.LBRACKET, string(l.ch))
	case ']':
		tok = l.newToken(token.RBRACKET, string(l.ch))
	case ',':
		tok = l.newToken(token.COMMA, string(l.ch))
	case ';':
		tok = l.newToken(token.SEMICOLON, string(l.ch))
	case ':':
		tok = l.newToken(token.COLON, string(l.ch))
	case '?':
		if l.peekChar() == '.' {
			l.readChar()
			tok = l.newToken(token.OPTIONAL, "?.")
		} else {
			tok = l.newToken(token.QUESTION, string(l.ch))
		}
	case '.':
		if l.peekChar() == '.' && l.peekCharN(2) == '.' {
			l.readChar()
			l.readChar()
			tok = l.newToken(token.SPREAD, "...")
		} else {
			tok = l.newToken(token.DOT, string(l.ch))
		}
	case '~':
		tok = l.newToken(token.BIT_NOT, string(l.ch))

	// Multi-character operators
	case '+':
		if l.peekChar() == '+' {
			l.readChar()
			tok = l.newToken(token.INCREMENT, "++")
		} else if l.peekChar() == '=' {
			l.readChar()
			tok = l.newToken(token.PLUS_ASSIGN, "+=")
		} else {
			tok = l.newToken(token.PLUS, string(l.ch))
		}
	case '-':
		if l.peekChar() == '-' {
			l.readChar()
			tok = l.newToken(token.DECREMENT, "--")
		} else if l.peekChar() == '=' {
			l.readChar()
			tok = l.newToken(token.MINUS_ASSIGN, "-=")
		} else if l.peekChar() == '>' {
			l.readChar()
			tok = l.newToken(token.LAMBDA, "->")
		} else {
			tok = l.newToken(token.MINUS, string(l.ch))
		}
	case '*':
		if l.peekChar() == '=' {
			l.readChar()
			tok = l.newToken(token.MUL_ASSIGN, "*=")
		} else if l.peekChar() == '*' {
			l.readChar()
			tok = l.newToken(token.POWER, "**")
		} else {
			tok = l.newToken(token.MULTIPLY, string(l.ch))
		}
	case '/':
		if l.peekChar() == '=' {
			l.readChar()
			tok = l.newToken(token.DIV_ASSIGN, "/=")
		} else if l.peekChar() == '/' {
			// Single-line comment
			l.skipLineComment()
			return l.NextToken()
		} else if l.peekChar() == '*' {
			// Multi-line comment
			l.skipBlockComment()
			return l.NextToken()
		} else {
			tok = l.newToken(token.DIVIDE, string(l.ch))
		}
	case '%':
		if l.peekChar() == '=' {
			l.readChar()
			tok = l.newToken(token.MOD_ASSIGN, "%=")
		} else {
			tok = l.newToken(token.MODULO, string(l.ch))
		}
	case '=':
		if l.peekChar() == '=' {
			l.readChar()
			tok = l.newToken(token.EQ, "==")
		} else if l.peekChar() == '>' {
			l.readChar()
			tok = l.newToken(token.ARROW, "=>")
		} else {
			tok = l.newToken(token.ASSIGN, string(l.ch))
		}
	case '!':
		if l.peekChar() == '=' {
			l.readChar()
			tok = l.newToken(token.NOT_EQ, "!=")
		} else {
			tok = l.newToken(token.NOT, string(l.ch))
		}
	case '<':
		if l.peekChar() == '=' {
			l.readChar()
			tok = l.newToken(token.LE, "<=")
		} else if l.peekChar() == '<' {
			l.readChar()
			tok = l.newToken(token.LSHIFT, "<<")
		} else {
			tok = l.newToken(token.LT, string(l.ch))
		}
	case '>':
		if l.peekChar() == '=' {
			l.readChar()
			tok = l.newToken(token.GE, ">=")
		} else if l.peekChar() == '>' {
			l.readChar()
			tok = l.newToken(token.RSHIFT, ">>")
		} else {
			tok = l.newToken(token.GT, string(l.ch))
		}
	case '&':
		if l.peekChar() == '&' {
			l.readChar()
			tok = l.newToken(token.AND, "&&")
		} else {
			tok = l.newToken(token.BIT_AND, string(l.ch))
		}
	case '|':
		if l.peekChar() == '|' {
			l.readChar()
			tok = l.newToken(token.OR, "||")
		} else {
			tok = l.newToken(token.BIT_OR, string(l.ch))
		}
	case '^':
		tok = l.newToken(token.BIT_XOR, string(l.ch))
	case '"':
		literal := l.readString('"')
		tok = l.newToken(token.STRING, literal)
	case '\'':
		literal := l.readString('\'')
		tok = l.newToken(token.STRING, literal)
	case '`':
		literal := l.readString('`')
		tok = l.newToken(token.STRING, literal)
	case '\n':
		tok = l.newToken(token.NEWLINE, "\\n")
	case 0:
		tok = l.newToken(token.EOF, "")
	default:
		if isLetter(l.ch) {
			literal := l.readIdentifier()
			typ := token.LookupIdent(literal)
			tok = l.newTokenLiteral(typ, literal)
		} else if isDigit(l.ch) {
			literal := l.readNumber()
			tok = l.newTokenLiteral(token.INT, literal)
		} else {
			tok = l.newToken(token.ILLEGAL, string(l.ch))
		}
	}

	l.readChar()
	return tok
}

// newToken creates a new token
func (l *Lexer) newToken(typ token.TokenType, literal string) token.Token {
	return token.Token{
		Type:    typ,
		Literal: literal,
		Line:    l.line,
		Column:  l.column - len(literal),
	}
}

// newTokenLiteral creates a new token with a literal value
func (l *Lexer) newTokenLiteral(typ token.TokenType, literal string) token.Token {
	return token.Token{
		Type:    typ,
		Literal: literal,
		Line:    l.line,
		Column:  l.column - len(literal),
	}
}

// skipWhitespaceExceptNewline skips whitespace except newlines
func (l *Lexer) skipWhitespaceExceptNewline() {
	for l.ch == ' ' || l.ch == '\t' || l.ch == '\r' {
		l.readChar()
	}
}

// skipLineComment skips a single-line comment
func (l *Lexer) skipLineComment() {
	for l.ch != '\n' && l.ch != 0 {
		l.readChar()
	}
}

// skipBlockComment skips a multi-line comment
func (l *Lexer) skipBlockComment() {
	l.readChar() // skip /
	l.readChar() // skip *
	for l.ch != 0 {
		if l.ch == '*' && l.peekChar() == '/' {
			l.readChar() // skip *
			l.readChar() // skip /
			break
		}
		l.readChar()
	}
}

// readIdentifier reads an identifier from the input
func (l *Lexer) readIdentifier() string {
	position := l.position
	for isLetter(l.ch) || isDigit(l.ch) || l.ch == '_' || l.ch == '$' {
		l.readChar()
	}
	return l.input[position:l.position]
}

// readNumber reads a number from the input
func (l *Lexer) readNumber() string {
	position := l.position
	hasDot := false

	for isDigit(l.ch) || (l.ch == '.' && !hasDot) {
		if l.ch == '.' {
			hasDot = true
		}
		l.readChar()
	}

	// Handle scientific notation (e.g., 1e10, 1.5e-3)
	if l.ch == 'e' || l.ch == 'E' {
		l.readChar()
		if l.ch == '+' || l.ch == '-' {
			l.readChar()
		}
		for isDigit(l.ch) {
			l.readChar()
		}
	}

	return l.input[position:l.position]
}

// readString reads a string literal from the input
func (l *Lexer) readString(quote byte) string {
	l.readChar() // skip opening quote
	position := l.position

	for l.ch != quote && l.ch != 0 {
		if l.ch == '\\' {
			l.readChar() // skip escape character
		}
		l.readChar()
	}

	literal := l.input[position:l.position]

	// Include the closing quote in the return
	if l.ch == quote {
		l.readChar() // skip closing quote
	}

	return literal
}

// Helper functions

func isLetter(ch byte) bool {
	return unicode.IsLetter(rune(ch))
}

func isDigit(ch byte) bool {
	return unicode.IsDigit(rune(ch))
}

// TokenizeAll returns all tokens from the input
func (l *Lexer) TokenizeAll() []token.Token {
	var tokens []token.Token
	for {
		tok := l.NextToken()
		tokens = append(tokens, tok)
		if tok.Type == token.EOF {
			break
		}
	}
	return tokens
}

