package lexer

import (
	"testing"

	"github.com/kimjindol2025/freelang-go/pkg/token"
)

func TestNextToken(t *testing.T) {
	input := `let x = 5;
let y = 10;
let add = func(a, b) {
  return a + b;
};
let result = add(5, 10);
!-/*5;
5 < 10 > 5;
if (5 < 10) {
  return true;
} else {
  return false;
}
10 == 10;
10 != 9;
`

	tests := []struct {
		expectedType    token.TokenType
		expectedLiteral string
	}{
