package lexer

import (
	"github.com/kimjindol2025/freelang-go/pkg/token"
)

// Lexer tokenizes FreeLang source code
type Lexer struct {
	input        string
	position     int  // current position in input
	readPosition int  // next position to read
	ch           byte // current char
	line         int
	column       int
}

// New creates a new lexer
func New(input string) *Lexer {
	l := &Lexer{
		input:  input,
		line:   1,
		column: 0,
	}
	l.readChar()
	return l
}

// readChar reads the next character
func (l *Lexer) readChar() {
	if l.readPosition >= len(l.input) {
		l.ch = 0 // EOF
	} else {
		l.ch = l.input[l.readPosition]
	}
	l.position = l.readPosition
	l.readPosition++
	l.column++

	if l.ch == '\n' {
		l.line++
		l.column = 0
	}
}

// peekChar looks at next char without consuming
func (l *Lexer) peekChar() byte {
	if l.readPosition >= len(l.input) {
		return 0
	}
	return l.input[l.readPosition]
}

// NextToken returns the next token
func (l *Lexer) NextToken() token.Token {
	l.skipWhitespace()

	var tok token.Token

	switch l.ch {
	case 0:
		tok = l.newToken(token.EOF, "")
	case '(':
		tok = l.newToken(token.LPAREN, "(")
		l.readChar()
	case ')':
		tok = l.newToken(token.RPAREN, ")")
		l.readChar()
	case '{':
		tok = l.newToken(token.LBRACE, "{")
		l.readChar()
	case '}':
		tok = l.newToken(token.RBRACE, "}")
		l.readChar()
	case '[':
		tok = l.newToken(token.LBRACKET, "[")
		l.readChar()
	case ']':
		tok = l.newToken(token.RBRACKET, "]")
		l.readChar()
	case ',':
		tok = l.newToken(token.COMMA, ",")
		l.readChar()
	case ';':
		tok = l.newToken(token.SEMICOLON, ";")
		l.readChar()
	case ':':
		tok = l.newToken(token.COLON, ":")
		l.readChar()
	case '.':
		if l.peekChar() == '.' && l.position+2 < len(l.input) && l.input[l.position+2] == '.' {
			tok = l.newToken(token.SPREAD, "...")
			l.readChar()
			l.readChar()
			l.readChar()
		} else {
			tok = l.newToken(token.DOT, ".")
			l.readChar()
		}
	case '?':
		if l.peekChar() == '.' {
			tok = l.newToken(token.OPTIONAL, "?.")
			l.readChar()
			l.readChar()
		} else {
			tok = l.newToken(token.QUESTION, "?")
			l.readChar()
		}
	case '+':
		if l.peekChar() == '+' {
			tok = l.newToken(token.INCREMENT, "++")
			l.readChar()
			l.readChar()
		} else if l.peekChar() == '=' {
			tok = l.newToken(token.PLUS_ASSIGN, "+=")
			l.readChar()
			l.readChar()
		} else {
			tok = l.newToken(token.PLUS, "+")
			l.readChar()
		}
	case '-':
		if l.peekChar() == '-' {
			tok = l.newToken(token.DECREMENT, "--")
			l.readChar()
			l.readChar()
		} else if l.peekChar() == '=' {
			tok = l.newToken(token.MINUS_ASSIGN, "-=")
			l.readChar()
			l.readChar()
		} else if l.peekChar() == '>' {
			tok = l.newToken(token.LAMBDA, "->")
			l.readChar()
			l.readChar()
		} else {
			tok = l.newToken(token.MINUS, "-")
			l.readChar()
		}
