			tok = l.newToken(token.POWER, "**")
			l.readChar()
			l.readChar()
		} else if l.peekChar() == '=' {
			tok = l.newToken(token.MUL_ASSIGN, "*=")
			l.readChar()
			l.readChar()
		} else {
			tok = l.newToken(token.MULTIPLY, "*")
			l.readChar()
		}
